.checkbox-box {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border: 2px solid var(--text-secondary);
  border-radius: 4px;
  background: transparent;
  display: grid;
  place-items: center;
  transition: border-color 0.12s ease, background 0.12s ease;
}

.checkbox-box svg {
  opacity: 0;
  transition: opacity 0.1s ease;
}

.option-item input[type="checkbox"]:checked + .checkbox-box {
  background: var(--accent);
  border-color: var(--accent);
}

.option-item input[type="checkbox"]:checked + .checkbox-box svg {
  opacity: 1;
}

/* checked state for the label row */
.option-item:has(input[type="checkbox"]:checked) label {
  background: var(--bg-checked);
  border-color: var(--accent);
  color: var(--text-primary);
}

/* Focus visible ring on the label */
.option-item input[type="checkbox"]:focus-visible + .checkbox-box {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.option-label-text {
  font-size: 0.95rem;
}

/* ── Submit button ────────────────────────────────────────── */
.submit-row {
  display: flex;
  justify-content: flex-end;
  margin-top: 1.75rem;
}

#submit-btn {
  background: var(--btn-bg);
  color: #fff;
  border: none;
  padding: 0.75rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  outline-offset: 3px;
}

#submit-btn:hover { background: var(--btn-bg-hover); }
#submit-btn:active { background: var(--btn-bg-active); transform: scale(0.98); }
#submit-btn:focus-visible { outline: 2px solid var(--border-focus); }

/* ── Results panel ────────────────────────────────────────── */
#results {
  margin-top: 2rem;
}

.results-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 1.75rem;
}

.results-card h2 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.score-display {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 0.25rem;
}

.score-label {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

.results-breakdown {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.result-item {
  padding: 0.85rem 1rem;
  border-radius: var(--radius-option);
  border: 1px solid var(--border);
  font-size: 0.9rem;
  line-height: 1.5;
}

.result-item.correct {
  background: rgba(63, 185, 80, 0.1);
  border-color: var(--success);
}

.result-item.incorrect {
  background: rgba(248, 81, 73, 0.1);
  border-color: var(--error);
}

.result-item .result-status {
  font-weight: 700;
  margin-right: 0.4em;
}

.result-item.correct .result-status { color: var(--success); }
.result-item.incorrect .result-status { color: var(--error); }

.result-detail {
  color: var(--text-secondary);
  margin-top: 0.2rem;
  font-size: 0.83rem;
}

/* ── Answered state after submit ──────────────────────────── */
.form-field.answered .option-item input[type="checkbox"] { pointer-events: none; }
.form-field.answered .option-item label { cursor: default; }

.option-item.reveal-correct label {
  border-color: var(--success) !important;
  background: rgba(63, 185, 80, 0.1) !important;
}

.option-item.reveal-wrong label {
  border-color: var(--error) !important;
  background: rgba(248, 81, 73, 0.1) !important;
}

/* ── Reflow at 320px ──────────────────────────────────────── */
@media (max-width: 400px) {
  .form-field { padding: 1rem; }
  .submit-row { justify-content: stretch; }
  #submit-btn { width: 100%; }
}
