*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0d1117;
  --bg-card:        #161b22;
  --bg-card-hover:  #1c2330;
  --bg-option:      #1e2530;
  --bg-option-hover:#252d3d;
  --bg-checked:     #1a2a4a;
  --border:         #30363d;
  --border-focus:   #58a6ff;
  --accent:         #58a6ff;
  --accent-pressed: #388bfd;
  --success:        #3fb950;
  --error:          #f85149;
  --text-primary:   #e6edf3;
  --text-secondary: #8b949e;
  --text-help:      #7d8590;
  --btn-bg:         #1f6feb;
  --btn-bg-hover:   #388bfd;
  --btn-bg-active:  #1158c7;
  --radius-card:    12px;
  --radius-option:  8px;
  --radius-btn:     8px;
}

html { font-size: 16px; }

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #000;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus { top: 1rem; }

/* ── Layout ───────────────────────────────────────────────── */
main {
  max-width: 680px;
  margin: 0 auto;
}

.quiz-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.quiz-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.quiz-header .subtitle {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

/* ── Form field (question card) ───────────────────────────── */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 1.5rem;
  margin-bottom: 1.25rem;
  transition: border-color 0.15s ease;
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* fieldset resets */
.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
  padding: 0;
  line-height: 1.4;
  width: 100%;
}

.question-number {
  display: inline-block;
  background: var(--accent);
  color: #000;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  margin-bottom: 0.5rem;
}

.help-text {
  font-size: 0.85rem;
  color: var(--text-help);
  margin-bottom: 1rem;
  padding: 0.6rem 0.75rem;
  background: rgba(88, 166, 255, 0.08);
  border-left: 3px solid var(--accent);
  border-radius: 0 4px 4px 0;
  line-height: 1.5;
}

/* ── Checkbox options ─────────────────────────────────────── */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--bg-option);
  border: 1px solid var(--border);
  border-radius: var(--radius-option);
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
  user-select: none;
}

.option-item label:hover {
  background: var(--bg-option-hover);
  border-color: #484f58;
}

/* Hide native checkbox visually but keep accessible */
.option-item input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom checkbox visual */
.checkbox-box {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border: 2px solid var(--text-secondary);
  border-radius: 4px;
  background: transparent;
  display: grid;
  place-items: center;
  transition: border-color 0.12s ease, background 0.12s ease;
