];

// ── Component helpers ─────────────────────────────────────────────────────────

/** Renders the SVG checkmark used inside the custom checkbox box. */
function CheckmarkSVG() {
  return `
    <svg width="12" height="10" viewBox="0 0 12 10" fill="none" aria-hidden="true" focusable="false">
      <path d="M1 5l3.5 3.5L11 1" stroke="#0d1117" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>`;
}

/** Renders a single checkbox option. */
function OptionComponent({ id, label, questionId }) {
  return `
    <li class="option-item" data-option-id="${id}">
      <label>
        <input
          type="checkbox"
          id="${id}"
          name="${questionId}"
          value="${id}"
          aria-describedby="${questionId}-desc"
        />
        <span class="checkbox-box" aria-hidden="true">${CheckmarkSVG()}</span>
        <span class="option-label-text">${label}</span>
      </label>
    </li>`;
}

/** Renders a full question card. */
function QuestionComponent(question) {
  const helpBlock = question.helpText
    ? `<p id="${question.id}-help" class="help-text">${question.helpText}</p>`
    : "";

  // If help text exists, add aria-describedby to the fieldset for screen readers
