+          <span class="question-number">Question ${question.number}</span><br>
+          ${question.text}
+        </legend>
+        ${helpBlock}
+        <ul class="options-list" role="group" id="${question.id}-desc">
+          ${optionsHTML}
+        </ul>
+      </fieldset>
+    </div>`;
+}
+
+/** Renders the entire quiz form. */
+function QuizComponent(questions) {
+  const questionsHTML = questions.map(QuestionComponent).join("");
+  return `
+    <section class="quiz-header">
+      <h1>Computer Languages Quiz</h1>
+      <p class="subtitle">Test your knowledge — select all correct answers for each question.</p>
+    </section>
+    <form id="quiz-form" novalidate>
+      ${questionsHTML}
+      <div class="submit-row">
+        <button type="submit" id="submit-btn">Submit Quiz</button>
+      </div>
+    </form>
+    <div id="results" aria-live="polite" aria-atomic="true"></div>`;
+}
+
+// ── Results rendering ─────────────────────────────────────────────────────────
+
+function gradeQuestion(question) {
+  const selected = new Set(
+    [...document.querySelectorAll(`input[name="${question.id}"]:checked`)].map(
+      (el) => el.value
+    )
+  );
+
+  // Sets are equal when same size and every member matches
+  const isCorrect =
+    selected.size === question.correctIds.size &&
+    [...selected].every((id) => question.correctIds.has(id));
+
+  return { selected, isCorrect };
+}
+
+function correctLabels(question) {
+  return question.options
+    .filter((o) => question.correctIds.has(o.id))
+    .map((o) => o.label)
+    .join(", ");
+}
+
+function ResultsComponent(grades) {
+  const score = grades.filter((g) => g.isCorrect).length;
+  const total = grades.length;
+  const allCorrect = score === total;
+  const pct = Math.round((score / total) * 100);
+
+  const breakdown = grades
+    .map(({ question, isCorrect, selected }) => {
+      const statusText = isCorrect ? "✓ Correct" : "✗ Incorrect";
+      const detail = isCorrect
+        ? ""
+        : `<p class="result-detail">Correct answer(s): ${correctLabels(question)}</p>`;
+      return `
+        <li class="result-item ${isCorrect ? "correct" : "incorrect"}">
+          <span class="result-status">${statusText}</span>
+          Question ${question.number}: ${question.text}
+          ${detail}
+        </li>`;
+    })
+    .join("");
+
+  return `
+    <div class="results-card">
+      <h2>Your Results</h2>
+      <div class="score-display">${pct}%</div>
+      <p class="score-label">${score} / ${total} correct${allCorrect ? " — Perfect score! 🎉" : ""}</p>
+      <ul class="results-breakdown">${breakdown}</ul>
+    </div>`;
+}
+
+// ── Reveal correct / incorrect on the question cards ─────────────────────────
+
+function revealAnswers(question, selected) {
+  const card = document.querySelector(`.form-field[data-question-id="${question.id}"]`);
+  if (!card) return;
+  card.classList.add("answered");
+
+  question.options.forEach((opt) => {
+    const item = card.querySelector(`[data-option-id="${opt.id}"]`);
+    if (!item) return;
+    const isCorrect = question.correctIds.has(opt.id);
+    const wasSelected = selected.has(opt.id);
+
+    if (isCorrect) {
+      item.classList.add("reveal-correct");
+    } else if (wasSelected && !isCorrect) {
+      item.classList.add("reveal-wrong");
+    }
+  });
+}
+
+// ── Bootstrap ─────────────────────────────────────────────────────────────────
+
+function init() {
+  const root = document.getElementById("quiz-root");
+  if (!root) return;
+
+  root.innerHTML = QuizComponent(QUESTIONS);
+
+  const form = document.getElementById("quiz-form");
+  form.addEventListener("submit", (e) => {
+    e.preventDefault();
+
+    const grades = QUESTIONS.map((question) => {
+      const { selected, isCorrect } = gradeQuestion(question);
+      revealAnswers(question, selected);
+      return { question, selected, isCorrect };
+    });
+
+    const resultsEl = document.getElementById("results");
+    resultsEl.innerHTML = ResultsComponent(grades);
+
+    // Disable submit
+    const btn = document.getElementById("submit-btn");
+    btn.disabled = true;
+    btn.textContent = "Submitted";
+
+    // Move focus to results for screen readers
+    resultsEl.querySelector(".results-card").setAttribute("tabindex", "-1");
+    resultsEl.querySelector(".results-card").focus();
+  });
+}
+
+document.addEventListener("DOMContentLoaded", init);
+
')

